if (!flow.get('tasks')) {
  flow.set('tasks', [
    { id: 1, title: 'Write the OpenAPI spec', status: 'done', priority: 'high' },
    { id: 2, title: 'Wire up the flow', status: 'open', priority: 'medium' }
  ]);
  flow.set('nextId', 3);
}
return null;

const tasks = flow.get('tasks') || [];
const { status, q, limit } = msg.parameters.query;
let out = tasks;
if (status) out = out.filter(t => t.status === status);
if (q) out = out.filter(t => t.title.toLowerCase().includes(String(q).toLowerCase()));
if (limit) out = out.slice(0, limit);
msg.statusCode = 200; msg.payload = out;
return msg;

const tasks = flow.get('tasks') || [];
const id = msg.parameters.path.taskId;
const task = tasks.find(t => t.id === id);
if (!task) { msg.error = { statusCode: 404, title: 'Not Found', detail: 'no task ' + id }; }
else { msg.statusCode = 200; msg.payload = task; }
return msg;

const tasks = flow.get('tasks') || [];
const id = flow.get('nextId') || (tasks.length + 1);
const task = Object.assign({ id, status: 'open', priority: 'medium' }, msg.payload);
tasks.push(task); flow.set('tasks', tasks); flow.set('nextId', id + 1);
msg.statusCode = 201; msg.payload = task;
return msg;

const tasks = flow.get('tasks') || [];
const id = msg.parameters.path.taskId;
const idx = tasks.findIndex(t => t.id === id);
if (idx < 0) { msg.error = { statusCode: 404, title: 'Not Found', detail: 'no task ' + id }; return msg; }
tasks[idx] = Object.assign({}, tasks[idx], msg.payload, { id });
flow.set('tasks', tasks);
msg.statusCode = 200; msg.payload = tasks[idx];
return msg;

const tasks = flow.get('tasks') || [];
const id = msg.parameters.path.taskId;
const idx = tasks.findIndex(t => t.id === id);
if (idx < 0) { msg.error = { statusCode: 404, title: 'Not Found', detail: 'no task ' + id }; return msg; }
tasks.splice(idx, 1); flow.set('tasks', tasks);
msg.statusCode = 204; msg.payload = undefined;
return msg;
